function wrapped(ctx,text,max){const lines=[];let line='';for(const ch of Array.from(text)){if(ctx.measureText(line+ch).width>max&&line){if('，。！？、；：）》」』】…'.includes(ch)){line+=ch;lines.push(line);line='';}else{lines.push(line);line=ch}}else line+=ch}if(line)lines.push(line);return lines;}
function sectionTitle(text){const line=text.trim();const marked=line.match(/^#{1,6}\s+(.+)$/u);if(marked)return marked[1].trim();if(state.chapterMode!=='auto'||line.length>80)return null;const num='[零〇一二三四五六七八九十百千万两0-9０-９]+';if(new RegExp('^第'+num+'[章节卷回部篇](?:[ \u3000:：、.．—-].*)?$','u').test(line)||new RegExp('^第'+num+'[章节卷回部篇]$','u').test(line))return line;if(/^(?:[0-9０-９]{1,4}|[零〇一二三四五六七八九十百千万两]{1,8})[、.．]?$/u.test(line))return line;return null}
